import{_ as s,H as i,f as e,i as t}from"./chunks/framework.Cvt1eIE0.js";const k=JSON.parse('{"title":"第二章：安装 Claude Code","description":"在你的电脑上安装 Claude Code","frontmatter":{"title":"第二章：安装 Claude Code","description":"在你的电脑上安装 Claude Code"},"headers":[],"relativePath":"guide/1-getting-started/2-installation.md","filePath":"guide/1-getting-started/2-installation.md"}'),n={name:"guide/1-getting-started/2-installation.md"};function l(h,a,d,o,p,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="第二章-安装-claude-code" tabindex="-1">第二章：安装 Claude Code <a class="header-anchor" href="#第二章-安装-claude-code" aria-label="Permalink to &quot;第二章：安装 Claude Code&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能在自己电脑上成功安装 Claude Code。</p></div><h2 id="什么是终端-命令行" tabindex="-1">什么是终端/命令行？ <a class="header-anchor" href="#什么是终端-命令行" aria-label="Permalink to &quot;什么是终端/命令行？&quot;">​</a></h2><p>在开始之前，我们需要先了解什么是<strong>终端</strong>（Terminal）。</p><p>终端是一个让你用文字命令来操作电脑的程序。就像电影里黑客用的那种黑底绿字的界面。</p><ul><li><strong>Windows</strong>：叫 PowerShell 或 Windows Terminal</li><li><strong>Mac</strong>：叫 Terminal（在 Applications &gt; Utilities 里）</li><li><strong>Linux</strong>：通常是 GNOME Terminal 或 Konsole</li></ul><h2 id="windows-用户安装步骤" tabindex="-1">Windows 用户安装步骤 <a class="header-anchor" href="#windows-用户安装步骤" aria-label="Permalink to &quot;Windows 用户安装步骤&quot;">​</a></h2><h3 id="_1-安装-windows-terminal-如果你没有的话" tabindex="-1">1. 安装 Windows Terminal（如果你没有的话） <a class="header-anchor" href="#_1-安装-windows-terminal-如果你没有的话" aria-label="Permalink to &quot;1. 安装 Windows Terminal（如果你没有的话）&quot;">​</a></h3><p>Windows 11 自带 Windows Terminal。如果你是 Windows 10，可以从 Microsoft Store 免费安装。</p><h3 id="_2-安装-claude-code" tabindex="-1">2. 安装 Claude Code <a class="header-anchor" href="#_2-安装-claude-code" aria-label="Permalink to &quot;2. 安装 Claude Code&quot;">​</a></h3><p>打开 PowerShell 或 Windows Terminal，输入以下命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">小提示</p><p>如果你看到提示需要管理员权限，右键选择&quot;以管理员身份运行&quot;终端。</p></div><h3 id="_3-验证安装成功" tabindex="-1">3. 验证安装成功 <a class="header-anchor" href="#_3-验证安装成功" aria-label="Permalink to &quot;3. 验证安装成功&quot;">​</a></h3><p>安装完成后，输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果看到版本号（比如 <code>0.1.0</code>），说明安装成功！</p><h2 id="mac-用户安装步骤" tabindex="-1">Mac 用户安装步骤 <a class="header-anchor" href="#mac-用户安装步骤" aria-label="Permalink to &quot;Mac 用户安装步骤&quot;">​</a></h2><h3 id="_1-打开-terminal" tabindex="-1">1. 打开 Terminal <a class="header-anchor" href="#_1-打开-terminal" aria-label="Permalink to &quot;1. 打开 Terminal&quot;">​</a></h3><p>按 <code>Command + Space</code>，搜索&quot;Terminal&quot;，回车打开。</p><h3 id="_2-安装-claude-code-1" tabindex="-1">2. 安装 Claude Code <a class="header-anchor" href="#_2-安装-claude-code-1" aria-label="Permalink to &quot;2. 安装 Claude Code&quot;">​</a></h3><p>在 Terminal 里输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><h3 id="_3-验证安装成功-1" tabindex="-1">3. 验证安装成功 <a class="header-anchor" href="#_3-验证安装成功-1" aria-label="Permalink to &quot;3. 验证安装成功&quot;">​</a></h3><p>输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>看到版本号就说明安装成功了。</p><h2 id="linux-用户安装步骤" tabindex="-1">Linux 用户安装步骤 <a class="header-anchor" href="#linux-用户安装步骤" aria-label="Permalink to &quot;Linux 用户安装步骤&quot;">​</a></h2><h3 id="_1-安装-node-js-如果没有" tabindex="-1">1. 安装 Node.js（如果没有） <a class="header-anchor" href="#_1-安装-node-js-如果没有" aria-label="Permalink to &quot;1. 安装 Node.js（如果没有）&quot;">​</a></h3><p>大多数 Linux 发行版可以通过包管理器安装 Node.js：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ubuntu/Debian</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodejs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fedora</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodejs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Arch Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodejs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span></span></code></pre></div><h3 id="_2-安装-claude-code-2" tabindex="-1">2. 安装 Claude Code <a class="header-anchor" href="#_2-安装-claude-code-2" aria-label="Permalink to &quot;2. 安装 Claude Code&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><h3 id="_3-验证安装成功-2" tabindex="-1">3. 验证安装成功 <a class="header-anchor" href="#_3-验证安装成功-2" aria-label="Permalink to &quot;3. 验证安装成功&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>会开关电脑、会打字。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 提示&quot;找不到命令&quot;？</strong></p><p>A: 可能需要重启终端。或者尝试完全关闭再重新打开。</p><p><strong>Q: 杀毒软件报警？</strong></p><p>A: 这是正常的，因为 Claude Code 会读写文件。信任该软件即可。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>在终端里输入 <code>claude --version</code>，确认看到版本号。</p><p>把截图发到评论区，和大家分享你的安装成功！</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>安装完成后，下一章我们会学习如何获取和配置 API Key。</p><p><a href="/guide/1-getting-started/3-api-key-setup.html">👉 第三章：API Key 获取与配置</a></p>`,48)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
